    "text": "What is the key advantage of primary data over secondary data?",
    "options": [
      {
        "text": "It requires no time or effort to collect",
        "isCorrect": false
      },
      {
        "text": "It is always free from any sample size requirement",
        "isCorrect": false
      },
      {
        "text": "It never requires tally marks",
        "isCorrect": false
      },
      {
        "text": "It is collected firsthand, making it directly relevant and reliable for the specific inquiry",
        "isCorrect": true
      }
    ],
    "correctAnswer": "D",
    "solution": "Step 1: Primary data is tailored to the exact objective of the investigation.\nStep 2: The investigator has direct control over the measurement methods and definitions.\nStep 3: Hence, high relevance and firsthand reliability is the key advantage.",
