    "questionCode": "MH-9-MTH1-7-7.2.2-OSC-219",
    "text": "What is the cumulative frequency of 'more than or equal to' type for the first class interval?",
    "options": [
      {
        "text": "Average frequency",
        "isCorrect": false
      },
      {
        "text": "Total frequency \\(N\\)",
        "isCorrect": true
      },
      {
        "text": "Frequency of the first class only",
        "isCorrect": false
      },
      {
        "text": "Zero",
        "isCorrect": false
      }
    ],
    "correctAnswer": "B",
    "solution": "Step 1: All observations in the dataset are greater than or equal to the lowest limit.\nStep 2: Therefore, the sum includes all frequencies \\(\\sum f_i = N\\).\nStep 3: Hence, it equals total frequency \\(N\\).",
